            if isinstance(period_ms, bool) or not isinstance(period_ms, int):
                raise ValueError(
                    f"周期毫秒 must be an int, got {type(period_ms).__name__}"
                )
            if period_ms < 0:
                raise ValueError(f"周期毫秒 must be >= 0, got {period_ms}")
        else:
            # v3-v6 迁移：配额周期补 0（不重置）。
            period_ms = 0
